SINA_SMART["biochem1-lipid-metabolism"] = {"lecture":"biochem1-lipid-metabolism","title":"Lipid metabolism","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"biochem1-lipid-metabolism:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e0","text":"Phospholipases A1, A2, C, D → IP3, DAG, arachidonic acid.","topic":"Catabolism","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e1","text":"Fatty acid oxidation: activation (2 ATP), carnitine transport, β-oxidation.","topic":"Catabolism","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e2","text":"β-oxidation: dehydrogenation, hydration, dehydrogenation, thiolysis → acetyl-CoA.","topic":"Catabolism","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e3","text":"C2n: n − 1 turns, n acetyl-CoA, n − 1 NADH and FADH₂; palmitate ≈ 106 ATP.","topic":"Catabolism","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e4","text":"Odd chains → propionyl-CoA → succinyl-CoA.","topic":"Catabolism","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e5","text":"Ketone bodies: liver mitochondria; fasting, diabetes; ketoacidosis; not for red cells.","topic":"Catabolism","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e6","text":"Fatty acid synthase (cytosol) builds palmitate; elongases/desaturases for longer ones.","topic":"Anabolism","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e7","text":"Omega-3 and omega-6 are essential.","topic":"Anabolism","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e8","text":"Cholesterol: HMG-CoA reductase, blocked by statins.","topic":"Anabolism","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-lipid-metabolism:e9","text":"Bile salts conjugated to taurine or glycine; vitamin D; steroid hormones.","topic":"Anabolism","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"ua7tik":"a","7qs5bu":"a","146pshn":"a","3ipaai":"a","12af9s1":"a","12ihaox":"a","1h46czd":"a","3gfnd7":"a","kzfj20":"a","hbc7f0":"a","rb9hge":"a","iej5g4":"a","1fp9kgf":"a","11z4o31":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"biochem1-lipid-metabolism:s0":{"s":0,"u":["Lipid metabolism covers catabolism (lipolysis, β-oxidation, ketone bodies) that yields energy, and anabolism (fatty acids, triglycerides, phospholipids, cholesterol) that builds stores, membranes and signalling molecules."],"dp":[]},"biochem1-lipid-metabolism:e0":{"s":1,"u":["Phospholipases A1, A2, C, D → IP3, DAG, arachidonic acid.","Phospholipases A1, A2, C and D release second messengers ( IP3, DAG , phosphatidic acid), free fatty acids such as arachidonic acid (precursor of prostaglandins) and remodel membranes."],"dp":[]},"biochem1-lipid-metabolism:e1":{"s":1,"u":["Fatty acid oxidation: activation (2 ATP), carnitine transport, β-oxidation.","Fatty acid oxidation : activation to acyl-CoA (costs 2 ATP), transport into mitochondria by carnitine , then β-oxidation (Lynen spiral): dehydrogenation (FADH₂), hydration, dehydrogenation (NADH), thiolysis releasing acetyl-CoA ."],"dp":[]},"biochem1-lipid-metabolism:e2":{"s":1,"u":["β-oxidation: dehydrogenation, hydration, dehydrogenation, thiolysis → acetyl-CoA.","Fatty acid oxidation : activation to acyl-CoA (costs 2 ATP), transport into mitochondria by carnitine , then β-oxidation (Lynen spiral): dehydrogenation (FADH₂), hydration, dehydrogenation (NADH), thiolysis releasing acetyl-CoA ."],"dp":[]},"biochem1-lipid-metabolism:e3":{"s":1,"u":["C2n: n − 1 turns, n acetyl-CoA, n − 1 NADH and FADH₂; palmitate ≈ 106 ATP.","For a fatty acid of 2n carbons: n − 1 turns , n acetyl-CoA , n − 1 NADH, n − 1 FADH₂; palmitate (C16) yields about 106 ATP .","Fatty acid oxidation : activation to acyl-CoA (costs 2 ATP), transport into mitochondria by carnitine , then β-oxidation (Lynen spiral): dehydrogenation (FADH₂), hydration, dehydrogenation (NADH), thiolysis releasing acetyl-CoA ."],"dp":[]},"biochem1-lipid-metabolism:e4":{"s":1,"u":["Odd chains → propionyl-CoA → succinyl-CoA.","Odd-chain fatty acids end with propionyl-CoA → succinyl-CoA (Krebs cycle); unsaturated fatty acids need extra enzymes."],"dp":[]},"biochem1-lipid-metabolism:e5":{"s":1,"u":["Ketone bodies: liver mitochondria; fasting, diabetes; ketoacidosis; not for red cells.","Ketone bodies (acetoacetate, β-hydroxybutyrate, acetone): water-soluble fuels made in liver mitochondria from acetyl-CoA during fasting , high-protein/low-carbohydrate diets and uncontrolled diabetes ; used by brain, heart, kidney and muscle (not red cells, which depend strictly on glucose)."],"dp":[{"h":"Why diabetes can make the blood acidic","t":"Without insulin, cells cannot take up glucose, so the body behaves as if starving: fat is broken down massively and the liver turns the flood of acetyl-CoA into ketone bodies. These are acids; when production outruns use, they consume bicarbonate and blood pH falls, causing diabetic ketoacidosis with acetone on the breath. Source: the lecture's ketone bodies slides."}]},"biochem1-lipid-metabolism:e6":{"s":2,"u":["Fatty acid synthase (cytosol) builds palmitate; elongases/desaturases for longer ones.","Longer and unsaturated fatty acids are made by elongases and desaturases (endoplasmic reticulum).","Fatty acid synthesis in the cytoplasm (liver, adipose tissue): activation (acetyl-CoA carboxylase → malonyl-CoA), then fatty acid synthase repeats four steps (Wakil spiral): condensation, reduction, dehydration, reduction, up to palmitate (C16)."],"dp":[]},"biochem1-lipid-metabolism:e7":{"s":2,"u":["Omega-3 and omega-6 are essential.","Omega-3 and omega-6 are essential (dietary)."],"dp":[]},"biochem1-lipid-metabolism:e8":{"s":2,"u":["Cholesterol: HMG-CoA reductase, blocked by statins.","Cholesterol : 43 steps from acetyl-CoA, consuming ATP and NADPH; key regulated enzyme HMG-CoA reductase , inhibited by statins ; hormonally regulated."],"dp":[]},"biochem1-lipid-metabolism:e9":{"s":2,"u":["Bile salts conjugated to taurine or glycine; vitamin D; steroid hormones.","Derivatives: bile salts (amphiphilic detergents made in liver, modified by colonic bacteria; primary bile salts are conjugated to taurine or glycine ; lipid digestion and cholesterol solubilisation), vitamin D and steroid hormones ."],"dp":[]}},"meta":{"ua7tik":{"a":"recall","vg":"biochem1-lipid-metabolism:e0/recall/1"},"7qs5bu":{"a":"recall","vg":"biochem1-lipid-metabolism:e0/recall/2"},"146pshn":{"a":"recall","vg":"biochem1-lipid-metabolism:e1/recall/1"},"3ipaai":{"a":"recall","vg":"biochem1-lipid-metabolism:e1/recall/2"},"12af9s1":{"a":"recall","vg":"biochem1-lipid-metabolism:e3/recall/1"},"12ihaox":{"a":"recall","vg":"biochem1-lipid-metabolism:e3/recall/2"},"1h46czd":{"a":"recall","vg":"biochem1-lipid-metabolism:e3/recall/3"},"3gfnd7":{"a":"recall","vg":"biochem1-lipid-metabolism:e4/recall/1"},"kzfj20":{"a":"recall","vg":"biochem1-lipid-metabolism:e5/recall/1"},"hbc7f0":{"a":"recall","vg":"biochem1-lipid-metabolism:e5/recall/1"},"rb9hge":{"a":"relationship","vg":"biochem1-lipid-metabolism:e5/relationship/1"},"iej5g4":{"a":"recall","vg":"biochem1-lipid-metabolism:e6/recall/1"},"1fp9kgf":{"a":"recall","vg":"biochem1-lipid-metabolism:e8/recall/1"},"11z4o31":{"a":"recall","vg":"biochem1-lipid-metabolism:e9/recall/1"}},"explRev":"946740491b05"};
